"""Órbita Sonora: API original y análisis RGB sincronizado píxel a píxel.

Arranque en Render: uvicorn main:app --host 0.0.0.0 --port $PORT
No decodifica audio en producción ni necesita dependencias de análisis adicionales.
"""
from collections import Counter
from pathlib import Path
from typing import Literal
import base64
import json
import math
import os
import struct
import time
import zlib

from fastapi import FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from fastapi.middleware.gzip import GZipMiddleware
from fastapi.responses import FileResponse, Response
from fastapi.staticfiles import StaticFiles

_DATOS_JSON = r'''{"version":2,"revision":"orbita-pixel-2026-11-01","canciones":[{"id":"end-of-line","titulo":"End Of Line","archivo_audio":"End Of Line - Daft Punk - TRON Legacy.mp3","sha256_audio":"b693fe8816256e103e91d1dbd3b15e7538bf7ab09928a5e26a08969ef4482de6","duracion_s":157.10621315192745,"muestras_pcm":6928384,"frecuencia_muestreo_hz":44100,"canales_audio":2,"bins_efectivos_hz":[[21.533203125,247.6318359375],[355.2978515625,495.263671875],[602.9296875,19998.96240234375]],"version":2,"lado":64,"pixeles":4096,"segundos_por_pixel":0.03835600907029479,"rgb_base64":"","activos_base64":"","referencia_potencia_db":-7.642405233274101,"rango_dinamico_db":70,"umbral_actividad_db":-60,"bandas":[{"canal":"R","min_hz":20,"max_hz":250},{"canal":"G","min_hz":350,"max_hz":500},{"canal":"B","min_hz":600,"max_hz":20000}],"guardas_hz":[[250,350],[500,600]],"metodo":{"magnitud":"potencia integrada de cada banda, promedio de canales de audio","ventana":"Hann","muestras_ventana":8192,"paso_muestras":512,"ventana_s":0.18575963718820862,"energia_pixel":"promedio temporal de potencia por intervalo T/4096","color":"dB de potencia normalizados sobre una escala común de 70 dB para todas las pistas y bandas","frecuencia_referencia":"máximo global de potencia de una banda por píxel","recorrido_exportado":"filas","fase_audio_conservada":false}},{"id":"derezzed","titulo":"Derezzed","archivo_audio":"Derezzed - Daft Punk - TRON Legacy.mp3","sha256_audio":"a5504d9bb3b33de1aba0683e225532a6986918547cf0efcd8138fdec8933f2b7","duracion_s":105.04707482993197,"muestras_pcm":4632576,"frecuencia_muestreo_hz":44100,"canales_audio":2,"bins_efectivos_hz":[[21.533203125,247.6318359375],[355.2978515625,495.263671875],[602.9296875,19998.96240234375]],"version":2,"lado":64,"pixeles":4096,"segundos_por_pixel":0.02564625850340136,"rgb_base64":"","activos_base64":"","referencia_potencia_db":-7.642405233274101,"rango_dinamico_db":70,"umbral_actividad_db":-60,"bandas":[{"canal":"R","min_hz":20,"max_hz":250},{"canal":"G","min_hz":350,"max_hz":500},{"canal":"B","min_hz":600,"max_hz":20000}],"guardas_hz":[[250,350],[500,600]],"metodo":{"magnitud":"potencia integrada de cada banda, promedio de canales de audio","ventana":"Hann","muestras_ventana":8192,"paso_muestras":512,"ventana_s":0.18575963718820862,"energia_pixel":"promedio temporal de potencia por intervalo T/4096","color":"dB de potencia normalizados sobre una escala común de 70 dB para todas las pistas y bandas","frecuencia_referencia":"máximo global de potencia de una banda por píxel","recorrido_exportado":"filas","fase_audio_conservada":false}},{"id":"the-son-of-flynn","titulo":"The Son Of Flynn","archivo_audio":"The Son Of Flynn - Daft Punk - TRON Legacy.mp3","sha256_audio":"d9f6fa87ba5aced01c639c5a6e2fcab0bc78288e6630f63cd445ed4efae859bd","duracion_s":96.03773242630386,"muestras_pcm":4235264,"frecuencia_muestreo_hz":44100,"canales_audio":2,"bins_efectivos_hz":[[21.533203125,247.6318359375],[355.2978515625,495.263671875],[602.9296875,19998.96240234375]],"version":2,"lado":64,"pixeles":4096,"segundos_por_pixel":0.02344671201814059,"rgb_base64":"","activos_base64":"","referencia_potencia_db":-7.642405233274101,"rango_dinamico_db":70,"umbral_actividad_db":-60,"bandas":[{"canal":"R","min_hz":20,"max_hz":250},{"canal":"G","min_hz":350,"max_hz":500},{"canal":"B","min_hz":600,"max_hz":20000}],"guardas_hz":[[250,350],[500,600]],"metodo":{"magnitud":"potencia integrada de cada banda, promedio de canales de audio","ventana":"Hann","muestras_ventana":8192,"paso_muestras":512,"ventana_s":0.18575963718820862,"energia_pixel":"promedio temporal de potencia por intervalo T/4096","color":"dB de potencia normalizados sobre una escala común de 70 dB para todas las pistas y bandas","frecuencia_referencia":"máximo global de potencia de una banda por píxel","recorrido_exportado":"filas","fase_audio_conservada":false}}]}'''


class OrbitaSonoraAPI:
    def __init__(self):
        self.preparar_datos()
        self.crear_aplicacion()
        self.registrar_rutas()

    def preparar_datos(self):
        self.raiz = Path(__file__).resolve().parent
        self.datos = json.loads(_DATOS_JSON)
        self.canciones = {c['id']: c for c in self.datos['canciones']}
        self.rgb = {k: base64.b64decode(c['rgb_base64']) for k, c in self.canciones.items()}
        self.activos = {k: base64.b64decode(c['activos_base64']) for k, c in self.canciones.items()}
        self.rutas = {}

    def crear_aplicacion(self):
        self.app = FastAPI(
            title='Órbita Sonora API',
            description='Backend oficial de Órbita Sonora / ORBIDATA con telemetría satelital GOES-16 y análisis RGB por píxel',
            version='2.0.0',
        )
        origenes = [o.strip() for o in os.getenv('CORS_ORIGINS', '*').split(',') if o.strip()]
        self.app.add_middleware(
            CORSMiddleware, allow_origins=origenes or ['*'],
            allow_credentials=False, allow_methods=['*'], allow_headers=['*'],
            expose_headers=['Content-Length', 'Content-Range', 'Accept-Ranges'],
        )
        self.app.add_middleware(GZipMiddleware, minimum_size=1024)

    def registrar_rutas(self):
        for ruta, funcion in [
            ('/', self.home), ('/api/datos', self.obtener_datos),
            ('/api/goes', self.obtener_goes), ('/api/canciones', self.obtener_canciones),
            ('/api/analisis/{cancion_id}', self.obtener_analisis),
            ('/api/estado/{cancion_id}', self.obtener_estado),
            ('/api/ocupacion/{cancion_id}', self.obtener_ocupacion),
            ('/api/imagenes/{cancion_id}/{canal}.png', self.obtener_imagen),
        ]:
            self.app.add_api_route(ruta, funcion, methods=['GET'])
        self.app.add_api_route('/rocola', self.mostrar_rocola, include_in_schema=False)
        self.app.add_api_route('/index.html', self.mostrar_rocola, include_in_schema=False)
        self.app.mount('/audio', StaticFiles(directory=str(self.raiz/'audio'), check_dir=False), name='audio')

    def home(self):
        return {'status': 'online', 'sistema': 'Órbita Sonora API - Servidor Activo'}

    def obtener_datos(self):
        return {
            'proyecto': 'Órbita Sonora', 'organizacion': 'ORBIDATA',
            'planeta': 'Tierra (GOES-16)', 'estado': 'Conectado',
            'origen': 'NOAA / NASA Open Data', 'album': 'TRON: Legacy OST',
            'autores': 'Daft Punk', 'genero': 'Electronic / Synthwave / Cyberpunk',
        }

    def obtener_goes(self):
        timestamp = int(time.time())
        return {
            'satelite': 'GOES-16 (GOES-East)', 'coordenadas': '75.2° W (Suramérica)',
            'tipo_captura': 'GeoColor Full Disk',
            'image_url': f'https://cdn.star.nesdis.noaa.gov/GOES16/ABI/FD/GEOCOLOR/1808x1808.jpg?t={timestamp}',
        }

    def buscar_cancion(self, cancion_id):
        if cancion_id not in self.canciones:
            raise HTTPException(status_code=404, detail='Canción no encontrada')
        return self.canciones[cancion_id]

    def obtener_canciones(self):
        return {
            'version': self.datos['version'], 'revision': self.datos['revision'],
            'reloj': 'HTMLMediaElement.currentTime del reproductor existente',
            'canciones': [
                {k: c[k] for k in ('id', 'titulo', 'archivo_audio', 'duracion_s', 'lado', 'pixeles', 'segundos_por_pixel', 'sha256_audio', 'bandas')}
                for c in self.canciones.values()
            ],
        }

    def obtener_analisis(self, cancion_id: str):
        return self.buscar_cancion(cancion_id)

    def coordenada_hilbert(self, indice, lado):
        x = y = 0
        temporal = indice
        escala = 1
        while escala < lado:
            rx = 1 & (temporal // 2)
            ry = 1 & (temporal ^ rx)
            if ry == 0:
                if rx == 1:
                    x, y = escala-1-x, escala-1-y
                x, y = y, x
            x += escala*rx
            y += escala*ry
            temporal //= 4
            escala *= 2
        return x, y

    def obtener_recorrido(self, lado, recorrido):
        clave = (lado, recorrido)
        if clave not in self.rutas:
            coordenadas = []
            for i in range(lado*lado):
                y, x = divmod(i, lado)
                if recorrido == 'serpentina' and y % 2:
                    x = lado-1-x
                elif recorrido == 'hilbert':
                    x, y = self.coordenada_hilbert(i, lado)
                coordenadas.append((x, y))
            self.rutas[clave] = tuple(coordenadas)
        return self.rutas[clave]

    def indice_en_tiempo(self, cancion, tiempo):
        if not math.isfinite(tiempo) or tiempo < 0:
            raise HTTPException(status_code=422, detail='Tiempo inválido')
        return min(cancion['pixeles']-1, int(tiempo/cancion['duracion_s']*cancion['pixeles']))

    def obtener_estado(
        self, cancion_id: str, tiempo: float = Query(default=0, ge=0),
        recorrido: Literal['filas', 'serpentina', 'hilbert'] = 'filas',
    ):
        c = self.buscar_cancion(cancion_id)
        indice = self.indice_en_tiempo(c, tiempo)
        x, y = self.obtener_recorrido(c['lado'], recorrido)[indice]
        color = list(self.rgb[cancion_id][indice*3:indice*3+3])
        return {
            'cancion_id': cancion_id, 'indice': indice, 'pixel': indice+1, 'x': x, 'y': y,
            'intervalo_s': [indice*c['segundos_por_pixel'], (indice+1)*c['segundos_por_pixel']],
            'rgb': color, 'intensidad_porcentaje': [v/255*100 for v in color],
            'activo': bool(self.activos[cancion_id][indice]), 'recorrido': recorrido,
        }

    def obtener_ocupacion(
        self, cancion_id: str, niveles: Literal[4, 8, 16] = 8,
        tiempo: float | None = Query(default=None, ge=0),
    ):
        c = self.buscar_cancion(cancion_id)
        limite = c['pixeles'] if tiempo is None else self.indice_en_tiempo(c, tiempo)+1
        secuencia = self.rgb[cancion_id]
        conteos = Counter()
        primeros = {}
        for i in range(limite):
            if not self.activos[cancion_id][i]:
                continue
            firma = tuple(min(niveles-1, v*niveles//256) for v in secuencia[3*i:3*i+3])
            conteos[firma] += 1
            primeros.setdefault(firma, i)
        total = sum(conteos.values())
        ordenadas = sorted(conteos.items(), key=lambda kv: (-kv[1], kv[0]))
        return {
            'cancion_id': cancion_id, 'niveles_por_banda': niveles,
            'criterio': 'coincidencia de tres intensidades RGB cuantizadas; silencios excluidos',
            'ambito': 'canción completa' if tiempo is None else 'hasta el cursor',
            'pixeles_considerados': limite, 'pixeles_activos': total,
            'firmas_distintas': len(conteos), 'unidad': 'intervalos de tiempo; no número de reproducciones',
            'firmas': [
                {'firma': list(firma), 'repeticiones': veces, 'ocupacion_pct': veces/total*100,
                 'duracion_s': veces*c['segundos_por_pixel'], 'primer_indice': primeros[firma]}
                for firma, veces in ordenadas
            ],
        }

    def crear_png(self, lado, pixeles):
        def bloque(tipo, datos):
            return struct.pack('!I', len(datos))+tipo+datos+struct.pack('!I', zlib.crc32(tipo+datos)&0xffffffff)
        filas = b''.join(b'\0'+pixeles[y*lado*3:(y+1)*lado*3] for y in range(lado))
        return (b'\x89PNG\r\n\x1a\n'+bloque(b'IHDR', struct.pack('!2I5B', lado, lado, 8, 2, 0, 0, 0))
                +bloque(b'IDAT', zlib.compress(filas, 9))+bloque(b'IEND', b''))

    def obtener_imagen(
        self, cancion_id: str, canal: Literal['RGB', 'R', 'G', 'B'],
        recorrido: Literal['filas', 'serpentina', 'hilbert'] = 'filas',
    ):
        c = self.buscar_cancion(cancion_id)
        imagen = bytearray(c['pixeles']*3)
        datos = self.rgb[cancion_id]
        seleccion = {'R': 0, 'G': 1, 'B': 2}.get(canal)
        for i, (x, y) in enumerate(self.obtener_recorrido(c['lado'], recorrido)):
            destino = (y*c['lado']+x)*3
            for banda in range(3):
                if seleccion is None or seleccion == banda:
                    imagen[destino+banda] = datos[3*i+banda]
        return Response(self.crear_png(c['lado'], bytes(imagen)), media_type='image/png',
                        headers={'Cache-Control': 'public, max-age=3600'})

    def mostrar_rocola(self):
        ruta = self.raiz/'index.html'
        if not ruta.is_file():
            raise HTTPException(status_code=404, detail='Coloca index.html junto a main.py')
        return FileResponse(ruta, media_type='text/html')


sistema = OrbitaSonoraAPI()
app = sistema.app
